@Internal
    public static FileSystem getUnguardedFileSystem(final URI fsUri) throws IOException {
        checkNotNull(fsUri, "file system URI");

        LOCK.lock();
        try {
            final URI uri;

            if (fsUri.getScheme() != null) {
                uri = fsUri;
            } else {
                // Apply the default fs scheme
                final URI defaultUri = getDefaultFsUri();
                URI rewrittenUri = null;

                try {
                    rewrittenUri =
                            new URI(
                                    defaultUri.getScheme(),
                                    null,
                                    defaultUri.getHost(),
                                    defaultUri.getPort(),
                                    fsUri.getPath(),
                                    null,
                                    null);
                } catch (URISyntaxException e) {
                    // for local URIs, we make one more try to repair the path by making it absolute
                    if (defaultUri.getScheme().equals("file")) {
                        try {
                            rewrittenUri =
                                    new URI(
                                            "file",
                                            null,
                                            new Path(new File(fsUri.getPath()).getAbsolutePath())
                                                    .toUri()
                                                    .getPath(),
                                            null);
                        } catch (URISyntaxException ignored) {
                            // could not help it...
                        }
                    }
                }

                if (rewrittenUri != null) {
                    uri = rewrittenUri;
                } else {
                    throw new IOException(
                            "The file system URI '"
                                    + fsUri
                                    + "' declares no scheme and cannot be interpreted relative to the default file system URI ("
                                    + defaultUri
                                    + ").");
                }
            }

            // print a helpful pointer for malformed local URIs (happens a lot to new users)
            if (uri.getScheme().equals("file")
                    && uri.getAuthority() != null
                    && !uri.getAuthority().isEmpty()) {
                String supposedUri = "file:///" + uri.getAuthority() + uri.getPath();

                throw new IOException(
                        "Found local file path with authority '"
                                + uri.getAuthority()
                                + "' in path '"
                                + uri.toString()
                                + "'. Hint: Did you forget a slash? (correct path would be '"
                                + supposedUri
                                + "')");
            }

            final FSKey key = new FSKey(uri.getScheme(), uri.getAuthority());

            // See if there is a file system object in the cache
            {
                FileSystem cached = CACHE.get(key);
                if (cached != null) {
                    return cached;
                }
            }

            // this "default" initialization makes sure that the FileSystem class works
            // even when not configured with an explicit Flink configuration, like on
            // JobManager or TaskManager setup
            if (FS_FACTORIES.isEmpty()) {
                initializeWithoutPlugins(new Configuration());
            }

            // Try to create a new file system
            final FileSystem fs;
            final FileSystemFactory factory = FS_FACTORIES.get(uri.getScheme());

            if (factory != null) {
                ClassLoader classLoader = factory.getClassLoader();
                try (TemporaryClassLoaderContext ignored =
                        TemporaryClassLoaderContext.of(classLoader)) {
                    fs = factory.create(uri);
                }
            } else if (!ALLOWED_FALLBACK_FILESYSTEMS.contains(uri.getScheme())
                    && DIRECTLY_SUPPORTED_FILESYSTEM.containsKey(uri.getScheme())) {
                final Collection<String> plugins =
                        DIRECTLY_SUPPORTED_FILESYSTEM.get(uri.getScheme());
                throw new UnsupportedFileSystemSchemeException(
                        String.format(
                                "Could not find a file system implementation for scheme '%s'. The scheme is "
                                        + "directly supported by Flink through the following plugin(s): %s. Please ensure that each "
                                        + "plugin resides within its own subfolder within the plugins directory. See https://nightlies.apache"
                                        + ".org/flink/flink-docs-stable/docs/deployment/filesystems/plugins/ for more information. If you want to "
                                        + "use a Hadoop file system for that scheme, please add the scheme to the configuration fs"
                                        + ".allowed-fallback-filesystems. For a full list of supported file systems, "
                                        + "please see https://nightlies.apache.org/flink/flink-docs-stable/ops/filesystems/.",
                                uri.getScheme(), String.join(", ", plugins)));
            } else {
                try {
                    fs = FALLBACK_FACTORY.create(uri);
                } catch (UnsupportedFileSystemSchemeException e) {
                    if (DIRECTLY_SUPPORTED_FILESYSTEM.containsKey(uri.getScheme())) {
                        final Collection<String> plugins =
                                DIRECTLY_SUPPORTED_FILESYSTEM.get(uri.getScheme());
                        throw new UnsupportedFileSystemSchemeException(
                                String.format(
                                        "Could not find a file system implementation for scheme '%s'. File system schemes "
                                                + "are supported by Flink through the following plugin(s): %s. "
                                                + "No file system to support this scheme could be loaded. Please ensure that each plugin is "
                                                + "configured properly and resides within its own subfolder in the plugins directory. "
                                                + "See https://nightlies.apache.org/flink/flink-docs-stable/docs/deployment/filesystems/plugins/ "
                                                + "for more information.",
                                        uri.getScheme(), String.join(", ", plugins)));
                    } else {
                        throw new UnsupportedFileSystemSchemeException(
                                "Could not find a file system implementation for scheme '"
                                        + uri.getScheme()
                                        + "'. The scheme is not directly supported by Flink and no Hadoop file system to "
                                        + "support this scheme could be loaded. For a full list of supported file systems, "
                                        + "please see https://nightlies.apache.org/flink/flink-docs-stable/ops/filesystems/.",
                                e);
                    }
                }
            }

            CACHE.put(key, fs);
            return fs;
        } finally {
            LOCK.unlock();
        }
    }

public void unionFields(Record other) {
        final int minFields = Math.min(this.numFields, other.numFields);
        final int maxFields = Math.max(this.numFields, other.numFields);

        final int[] offsets = this.offsets.length >= maxFields ? this.offsets : new int[maxFields];
        final int[] lengths = this.lengths.length >= maxFields ? this.lengths : new int[maxFields];

        if (!(this.isModified() || other.isModified())) {
            // handle the special (but common) case where both records have a valid binary
            // representation differently
            // allocate space for the switchBuffer first
            final int estimatedLength = this.binaryLen + other.binaryLen;
            this.serializer.memory =
                    (this.switchBuffer != null && this.switchBuffer.length >= estimatedLength)
                            ? this.switchBuffer
                            : new byte[estimatedLength];
            this.serializer.position = 0;

            try {
                // common loop for both records
                for (int i = 0; i < minFields; i++) {
                    final int thisOff = this.offsets[i];
                    if (thisOff == NULL_INDICATOR_OFFSET) {
                        final int otherOff = other.offsets[i];
                        if (otherOff == NULL_INDICATOR_OFFSET) {
                            offsets[i] = NULL_INDICATOR_OFFSET;
                        } else {
                            // take field from other record
                            offsets[i] = this.serializer.position;
                            this.serializer.write(other.binaryData, otherOff, other.lengths[i]);
                            lengths[i] = other.lengths[i];
                        }
                    } else {
                        // copy field from this one
                        offsets[i] = this.serializer.position;
                        this.serializer.write(this.binaryData, thisOff, this.lengths[i]);
                        lengths[i] = this.lengths[i];
                    }
                }

                // add the trailing fields from one record
                if (minFields != maxFields) {
                    final Record sourceForRemainder = this.numFields > minFields ? this : other;
                    int begin = -1;
                    int end = -1;
                    int offsetDelta = 0;

                    // go through the offsets, find the non-null fields to account for the remaining
                    // data
                    for (int k = minFields; k < maxFields; k++) {
                        final int off = sourceForRemainder.offsets[k];
                        if (off == NULL_INDICATOR_OFFSET) {
                            offsets[k] = NULL_INDICATOR_OFFSET;
                        } else {
                            end = sourceForRemainder.offsets[k] + sourceForRemainder.lengths[k];
                            if (begin == -1) {
                                // first non null column in the remainder
                                begin = sourceForRemainder.offsets[k];
                                offsetDelta = this.serializer.position - begin;
                            }
                            offsets[k] = sourceForRemainder.offsets[k] + offsetDelta;
                        }
                    }

                    // copy the remaining fields directly as binary
                    if (begin != -1) {
                        this.serializer.write(sourceForRemainder.binaryData, begin, end - begin);
                    }

                    // the lengths can be copied directly
                    if (lengths != sourceForRemainder.lengths) {
                        System.arraycopy(
                                sourceForRemainder.lengths,
                                minFields,
                                lengths,
                                minFields,
                                maxFields - minFields);
                    }
                }
            } catch (Exception ioex) {
                throw new RuntimeException(
                        "Error creating field union of record data" + ioex.getMessage() == null
                                ? "."
                                : ": " + ioex.getMessage(),
                        ioex);
            }
        } else {
            // the general case, where at least one of the two records has a binary representation
            // that is not in sync.
            final int estimatedLength =
                    (this.binaryLen > 0
                                    ? this.binaryLen
                                    : this.numFields * DEFAULT_FIELD_LEN_ESTIMATE)
                            + (other.binaryLen > 0
                                    ? other.binaryLen
                                    : other.numFields * DEFAULT_FIELD_LEN_ESTIMATE);
            this.serializer.memory =
                    (this.switchBuffer != null && this.switchBuffer.length >= estimatedLength)
                            ? this.switchBuffer
                            : new byte[estimatedLength];
            this.serializer.position = 0;

            try {
                // common loop for both records
                for (int i = 0; i < minFields; i++) {
                    final int thisOff = this.offsets[i];
                    if (thisOff == NULL_INDICATOR_OFFSET) {
                        final int otherOff = other.offsets[i];
                        if (otherOff == NULL_INDICATOR_OFFSET) {
                            offsets[i] = NULL_INDICATOR_OFFSET;
                        } else if (otherOff == MODIFIED_INDICATOR_OFFSET) {
                            // serialize modified field from other record
                            offsets[i] = this.serializer.position;
                            other.writeFields[i].write(this.serializer);
                            lengths[i] = this.serializer.position - offsets[i];
                        } else {
                            // take field from other record binary
                            offsets[i] = this.serializer.position;
                            this.serializer.write(other.binaryData, otherOff, other.lengths[i]);
                            lengths[i] = other.lengths[i];
                        }
                    } else if (thisOff == MODIFIED_INDICATOR_OFFSET) {
                        // serialize modified field from this record
                        offsets[i] = this.serializer.position;
                        this.writeFields[i].write(this.serializer);
                        lengths[i] = this.serializer.position - offsets[i];
                    } else {
                        // copy field from this one
                        offsets[i] = this.serializer.position;
                        this.serializer.write(this.binaryData, thisOff, this.lengths[i]);
                        lengths[i] = this.lengths[i];
                    }
                }

                // add the trailing fields from one record
                if (minFields != maxFields) {
                    final Record sourceForRemainder = this.numFields > minFields ? this : other;

                    // go through the offsets, find the non-null fields
                    for (int k = minFields; k < maxFields; k++) {
                        final int off = sourceForRemainder.offsets[k];
                        if (off == NULL_INDICATOR_OFFSET) {
                            offsets[k] = NULL_INDICATOR_OFFSET;
                        } else if (off == MODIFIED_INDICATOR_OFFSET) {
                            // serialize modified field from the source record
                            offsets[k] = this.serializer.position;
                            sourceForRemainder.writeFields[k].write(this.serializer);
                            lengths[k] = this.serializer.position - offsets[k];
                        } else {
                            // copy field from the source record binary
                            offsets[k] = this.serializer.position;
                            final int len = sourceForRemainder.lengths[k];
                            this.serializer.write(sourceForRemainder.binaryData, off, len);
                            lengths[k] = len;
                        }
                    }
                }
            } catch (Exception ioex) {
                throw new RuntimeException(
                        "Error creating field union of record data" + ioex.getMessage() == null
                                ? "."
                                : ": " + ioex.getMessage(),
                        ioex);
            }
        }

        serializeHeader(this.serializer, offsets, maxFields);

        // set the fields
        this.switchBuffer = this.binaryData;
        this.binaryData = serializer.memory;
        this.binaryLen = serializer.position;

        this.numFields = maxFields;
        this.offsets = offsets;
        this.lengths = lengths;

        this.firstModifiedPos = Integer.MAX_VALUE;

        // make sure that the object arrays reflect the size as well
        if (this.readFields == null || this.readFields.length < maxFields) {
            final Value[] na = new Value[maxFields];
            System.arraycopy(this.readFields, 0, na, 0, this.readFields.length);
            this.readFields = na;
        }
        this.writeFields =
                (this.writeFields == null || this.writeFields.length < maxFields)
                        ? new Value[maxFields]
                        : this.writeFields;
    }

