@Override
    public FileSystem create(URI fsUri) throws IOException {
        checkNotNull(fsUri, "fsUri");

        final String scheme = fsUri.getScheme();
        checkArgument(scheme != null, "file system has null scheme");

        // from here on, we need to handle errors due to missing optional
        // dependency classes
        try {
            // -- (1) get the loaded Hadoop config (or fall back to one loaded from the classpath)

            final org.apache.hadoop.conf.Configuration hadoopConfig;
            if (this.hadoopConfig != null) {
                hadoopConfig = this.hadoopConfig;
            } else if (flinkConfig != null) {
                hadoopConfig = HadoopUtils.getHadoopConfiguration(flinkConfig);
                this.hadoopConfig = hadoopConfig;
            } else {
                LOG.warn(
                        "Hadoop configuration has not been explicitly initialized prior to loading a Hadoop file system."
                                + " Using configuration from the classpath.");

                hadoopConfig = new org.apache.hadoop.conf.Configuration();
            }

            // -- (2) get the Hadoop file system class for that scheme

            final Class<? extends org.apache.hadoop.fs.FileSystem> fsClass;
            try {
                fsClass = org.apache.hadoop.fs.FileSystem.getFileSystemClass(scheme, hadoopConfig);
            } catch (IOException e) {
                throw new UnsupportedFileSystemSchemeException(
                        "Hadoop File System abstraction does not support scheme '"
                                + scheme
                                + "'. "
                                + "Either no file system implementation exists for that scheme, "
                                + "or the relevant classes are missing from the classpath.",
                        e);
            }

            // -- (3) instantiate the Hadoop file system

            LOG.debug(
                    "Instantiating for file system scheme {} Hadoop File System {}",
                    scheme,
                    fsClass.getName());

            final org.apache.hadoop.fs.FileSystem hadoopFs = fsClass.newInstance();

            // -- (4) create the proper URI to initialize the file system

            final URI initUri;
            if (fsUri.getAuthority() != null) {
                initUri = fsUri;
            } else {
                if (LOG.isDebugEnabled()) {
                    LOG.debug(
                            "URI {} does not specify file system authority, trying to load default authority (fs.defaultFS)",
                            fsUri);
                }

                String configEntry = hadoopConfig.get("fs.defaultFS", null);
                if (configEntry == null) {
                    // fs.default.name deprecated as of hadoop 2.2.0 - see
                    // http://hadoop.apache.org/docs/current/hadoop-project-dist/hadoop-common/DeprecatedProperties.html
                    configEntry = hadoopConfig.get("fs.default.name", null);
                }

                if (LOG.isDebugEnabled()) {
                    LOG.debug("Hadoop's 'fs.defaultFS' is set to {}", configEntry);
                }

                if (configEntry == null) {
                    throw new IOException(
                            getMissingAuthorityErrorPrefix(fsUri)
                                    + "Hadoop configuration did not contain an entry for the default file system ('fs.defaultFS').");
                } else {
                    try {
                        initUri = URI.create(configEntry);
                    } catch (IllegalArgumentException e) {
                        throw new IOException(
                                getMissingAuthorityErrorPrefix(fsUri)
                                        + "The configuration contains an invalid file system default name "
                                        + "('fs.default.name' or 'fs.defaultFS'): "
                                        + configEntry);
                    }

                    if (initUri.getAuthority() == null) {
                        throw new IOException(
                                getMissingAuthorityErrorPrefix(fsUri)
                                        + "Hadoop configuration for default file system ('fs.default.name' or 'fs.defaultFS') "
                                        + "contains no valid authority component (like hdfs namenode, S3 host, etc)");
                    }
                }
            }

            // -- (5) configure the Hadoop file system

            try {
                hadoopFs.initialize(initUri, hadoopConfig);
            } catch (UnknownHostException e) {
                String message =
                        "The Hadoop file system's authority ("
                                + initUri.getAuthority()
                                + "), specified by either the file URI or the configuration, cannot be resolved.";

                throw new IOException(message, e);
            }

            HadoopFileSystem fs = new HadoopFileSystem(hadoopFs);

            // create the Flink file system, optionally limiting the open connections
            if (flinkConfig != null) {
                return limitIfConfigured(fs, scheme, flinkConfig);
            } else {
                return fs;
            }
        } catch (ReflectiveOperationException | LinkageError e) {
            throw new UnsupportedFileSystemSchemeException(
                    "Cannot support file system for '"
                            + fsUri.getScheme()
                            + "' via Hadoop, because Hadoop is not in the classpath, or some classes "
                            + "are missing from the classpath.",
                    e);
        } catch (IOException e) {
            throw e;
        } catch (Exception e) {
            throw new IOException("Cannot instantiate file system for URI: " + fsUri, e);
        }
    }

@Override
        protected void doEndElement(String uri, String name, String qName) {

            if (in("ListBucketAnalyticsConfigurationsResult")) {
                if (name.equals("AnalyticsConfiguration")) {
                    if (result.getAnalyticsConfigurationList() == null) {
                        result.setAnalyticsConfigurationList(
                                new ArrayList<AnalyticsConfiguration>());
                    }
                    result.getAnalyticsConfigurationList().add(currentConfiguration);
                    currentConfiguration = null;
                } else if (name.equals("IsTruncated")) {
                    result.setTruncated("true".equals(getText()));
                } else if (name.equals("ContinuationToken")) {
                    result.setContinuationToken(getText());
                } else if (name.equals("NextContinuationToken")) {
                    result.setNextContinuationToken(getText());
                }
            } else if (in("ListBucketAnalyticsConfigurationsResult", "AnalyticsConfiguration")) {
                if (name.equals("Id")) {
                    currentConfiguration.setId(getText());
                } else if (name.equals("Filter")) {
                    currentConfiguration.setFilter(currentFilter);
                } else if (name.equals("StorageClassAnalysis")) {
                    currentConfiguration.setStorageClassAnalysis(storageClassAnalysis);
                }
            } else if (in(
                    "ListBucketAnalyticsConfigurationsResult",
                    "AnalyticsConfiguration",
                    "Filter")) {
                if (name.equals("Prefix")) {
                    currentFilter.setPredicate(new AnalyticsPrefixPredicate(getText()));
                } else if (name.equals("Tag")) {
                    currentFilter.setPredicate(
                            new AnalyticsTagPredicate(new Tag(currentTagKey, currentTagValue)));
                    currentTagKey = null;
                    currentTagValue = null;
                } else if (name.equals("And")) {
                    currentFilter.setPredicate(new AnalyticsAndOperator(andOperandsList));
                    andOperandsList = null;
                }
            } else if (in(
                    "ListBucketAnalyticsConfigurationsResult",
                    "AnalyticsConfiguration",
                    "Filter",
                    "Tag")) {
                if (name.equals("Key")) {
                    currentTagKey = getText();
                } else if (name.equals("Value")) {
                    currentTagValue = getText();
                }
            } else if (in(
                    "ListBucketAnalyticsConfigurationsResult",
                    "AnalyticsConfiguration",
                    "Filter",
                    "And")) {
                if (name.equals("Prefix")) {
                    andOperandsList.add(new AnalyticsPrefixPredicate(getText()));
                } else if (name.equals("Tag")) {
                    andOperandsList.add(
                            new AnalyticsTagPredicate(new Tag(currentTagKey, currentTagValue)));
                    currentTagKey = null;
                    currentTagValue = null;
                }
            } else if (in(
                    "ListBucketAnalyticsConfigurationsResult",
                    "AnalyticsConfiguration",
                    "Filter",
                    "And",
                    "Tag")) {
                if (name.equals("Key")) {
                    currentTagKey = getText();
                } else if (name.equals("Value")) {
                    currentTagValue = getText();
                }
            } else if (in(
                    "ListBucketAnalyticsConfigurationsResult",
                    "AnalyticsConfiguration",
                    "StorageClassAnalysis")) {
                if (name.equals("DataExport")) {
                    storageClassAnalysis.setDataExport(dataExport);
                }
            } else if (in(
                    "ListBucketAnalyticsConfigurationsResult",
                    "AnalyticsConfiguration",
                    "StorageClassAnalysis",
                    "DataExport")) {
                if (name.equals("OutputSchemaVersion")) {
                    dataExport.setOutputSchemaVersion(getText());
                } else if (name.equals("Destination")) {
                    dataExport.setDestination(destination);
                }
            } else if (in(
                    "ListBucketAnalyticsConfigurationsResult",
                    "AnalyticsConfiguration",
                    "StorageClassAnalysis",
                    "DataExport",
                    "Destination")) {
                if (name.equals("S3BucketDestination")) {
                    destination.setS3BucketDestination(s3BucketDestination);
                }
            } else if (in(
                    "ListBucketAnalyticsConfigurationsResult",
                    "AnalyticsConfiguration",
                    "StorageClassAnalysis",
                    "DataExport",
                    "Destination",
                    "S3BucketDestination")) {
                if (name.equals("Format")) {
                    s3BucketDestination.setFormat(getText());
                } else if (name.equals("BucketAccountId")) {
                    s3BucketDestination.setBucketAccountId(getText());
                } else if (name.equals("Bucket")) {
                    s3BucketDestination.setBucketArn(getText());
                } else if (name.equals("Prefix")) {
                    s3BucketDestination.setPrefix(getText());
                }
            }
        }

@Override
    public FileSystem create(URI fsUri) throws IOException {
        Configuration config = this.flinkConfig;
        if (config == null) {
            config = new Configuration();
        }

        String accessKey = config.get(ACCESS_KEY);
        String secretKey = config.get(SECRET_KEY);
        String region = config.get(REGION);
        String endpoint = config.get(ENDPOINT);
        boolean pathStyleAccess = config.get(PATH_STYLE_ACCESS);
        String sseType = config.get(SSE_TYPE);
        String sseKmsKeyId = config.get(SSE_KMS_KEY_ID);
        String assumeRoleArn = config.get(ASSUME_ROLE_ARN);
        String assumeRoleExternalId = config.get(ASSUME_ROLE_EXTERNAL_ID);
        String assumeRoleSessionName = config.get(ASSUME_ROLE_SESSION_NAME);
        int assumeRoleSessionDuration = config.get(ASSUME_ROLE_SESSION_DURATION_SECONDS);
        String credentialsProviderClasses = config.get(AWS_CREDENTIALS_PROVIDER);
        boolean deleteBatchEnabled = config.get(DELETE_BATCH_ENABLED);

        // Apply bucket-specific overrides
        String bucketName = fsUri.getHost();
        if (StringUtils.isNullOrWhitespaceOnly(bucketName)) {
            throw new IOException("Invalid S3 URI: missing or empty bucket name in URI: " + fsUri);
        }
        if (bucketConfigProvider != null) {
            S3BucketConfig overrides = bucketConfigProvider.getBucketConfig(bucketName);
            if (overrides != null) {
                LOG.debug(
                        "Applying bucket-specific configuration for bucket '{}': {}",
                        bucketName,
                        overrides);
                accessKey = firstNonNull(overrides.getAccessKey(), accessKey);
                secretKey = firstNonNull(overrides.getSecretKey(), secretKey);
                region = firstNonNull(overrides.getRegion(), region);
                endpoint = firstNonNull(overrides.getEndpoint(), endpoint);
                sseType = firstNonNull(overrides.getSseType(), sseType);
                sseKmsKeyId = firstNonNull(overrides.getSseKmsKeyId(), sseKmsKeyId);
                assumeRoleArn = firstNonNull(overrides.getAssumeRoleArn(), assumeRoleArn);
                assumeRoleExternalId =
                        firstNonNull(overrides.getAssumeRoleExternalId(), assumeRoleExternalId);
                assumeRoleSessionName =
                        firstNonNull(overrides.getAssumeRoleSessionName(), assumeRoleSessionName);
                credentialsProviderClasses =
                        firstNonNull(
                                overrides.getCredentialsProvider(), credentialsProviderClasses);
                if (overrides.getPathStyleAccess() != null) {
                    pathStyleAccess = overrides.getPathStyleAccess();
                }
                if (overrides.getAssumeRoleSessionDurationSeconds() != null) {
                    assumeRoleSessionDuration = overrides.getAssumeRoleSessionDurationSeconds();
                }
                if (overrides.getDeleteBatchEnabled() != null) {
                    deleteBatchEnabled = overrides.getDeleteBatchEnabled();
                }
            }
        }

        S3EncryptionConfig encryptionConfig =
                S3EncryptionConfig.fromConfig(
                        sseType,
                        sseKmsKeyId,
                        config.getOptional(SSE_KMS_ENCRYPTION_CONTEXT)
                                .orElse(Collections.emptyMap()));

        String entropyInjectionKey = config.get(ENTROPY_INJECT_KEY_OPTION);
        int numEntropyChars = -1;
        if (entropyInjectionKey != null) {
            if (entropyInjectionKey.matches(INVALID_ENTROPY_KEY_CHARS)) {
                throw new IllegalConfigurationException(
                        "Invalid character in entropy injection key: " + entropyInjectionKey);
            }
            numEntropyChars = config.get(ENTROPY_INJECT_LENGTH_OPTION);
            if (numEntropyChars <= 0) {
                throw new IllegalConfigurationException(
                        ENTROPY_INJECT_LENGTH_OPTION.key() + " must be > 0");
            }
        }

        final String[] localTmpDirectories = ConfigurationUtils.parseTempDirectories(config);
        Preconditions.checkArgument(
                localTmpDirectories.length > 0,
                "No temporary directories configured. "
                        + "Please configure at least one temp directory via 'io.tmp.dirs' or similar.");
        final String localTmpDirectory = localTmpDirectories[0];

        final long s3minPartSize = config.get(PART_UPLOAD_MIN_SIZE);
        final int maxConcurrentUploads = config.get(MAX_CONCURRENT_UPLOADS);

        // Validate part size: S3 requires minimum 5MB and maximum 5GB per part
        Preconditions.checkArgument(
                s3minPartSize >= S3_MULTIPART_MIN_PART_SIZE,
                "%s must be at least 5MB (5242880 bytes), but was %s bytes",
                PART_UPLOAD_MIN_SIZE.key(),
                s3minPartSize);
        Preconditions.checkArgument(
                s3minPartSize <= 5L * 1024 * 1024 * 1024,
                "%s must not exceed 5GB (5368709120 bytes), but was %s bytes",
                PART_UPLOAD_MIN_SIZE.key(),
                s3minPartSize);
        Preconditions.checkArgument(
                maxConcurrentUploads > 0,
                "%s must be positive, but was %s",
                MAX_CONCURRENT_UPLOADS.key(),
                maxConcurrentUploads);

        boolean useAsyncOperations = config.get(USE_ASYNC_OPERATIONS);
        int configuredReadBufferSize = config.get(READ_BUFFER_SIZE);
        int readBufferSize = Math.max(256 * 1024, configuredReadBufferSize);
        if (readBufferSize != configuredReadBufferSize) {
            LOG.warn(
                    "{} value {} was below 64KB. Using {} instead.",
                    READ_BUFFER_SIZE.key(),
                    configuredReadBufferSize,
                    readBufferSize);
        }

        final int maxConnections = config.get(MAX_CONNECTIONS);
        Preconditions.checkArgument(
                maxConnections > 0,
                "'%s' must be a positive integer, but was %s",
                MAX_CONNECTIONS.key(),
                maxConnections);

        final boolean crtEnabled = config.get(CRT_ENABLED);

        // CRT-only options. Validated only when CRT is enabled (mirroring the bulk-copy gating
        // below); when CRT is disabled these options are ignored. Unset optional values fall back
        // to the CRT runtime's own defaults.
        final Double crtTargetThroughputGbps =
                config.getOptional(CRT_TARGET_THROUGHPUT_GBPS).orElse(null);
        final MemorySize crtMaxNativeMemoryLimit =
                config.getOptional(CRT_MAX_NATIVE_MEMORY_LIMIT).orElse(null);
        final MemorySize crtReadBufferSize = config.getOptional(CRT_READ_BUFFER_SIZE).orElse(null);
        final int crtMaxConcurrency = config.get(CRT_MAX_CONCURRENCY);
        if (crtEnabled) {
            if (crtTargetThroughputGbps != null) {
                Preconditions.checkArgument(
                        crtTargetThroughputGbps > 0,
                        "'%s' must be positive, but was %s",
                        CRT_TARGET_THROUGHPUT_GBPS.key(),
                        crtTargetThroughputGbps);
            }
            if (crtMaxNativeMemoryLimit != null) {
                Preconditions.checkArgument(
                        crtMaxNativeMemoryLimit.getBytes() > 0,
                        "'%s' must be positive, but was %s",
                        CRT_MAX_NATIVE_MEMORY_LIMIT.key(),
                        crtMaxNativeMemoryLimit);
            }
            if (crtReadBufferSize != null) {
                Preconditions.checkArgument(
                        crtReadBufferSize.getBytes() > 0,
                        "'%s' must be positive, but was %s",
                        CRT_READ_BUFFER_SIZE.key(),
                        crtReadBufferSize);
            }
            Preconditions.checkArgument(
                    crtMaxConcurrency > 0,
                    "'%s' must be a positive integer, but was %s",
                    CRT_MAX_CONCURRENCY.key(),
                    crtMaxConcurrency);
        }

        final boolean bulkCopyEnabled = config.get(BULK_COPY_ENABLED);
        final int bulkCopyMaxConcurrent = config.get(BULK_COPY_MAX_CONCURRENT);
        final int bulkCopyDownloadBufferSize = config.get(BULK_COPY_DOWNLOAD_BUFFER_SIZE);
        if (bulkCopyEnabled) {
            Preconditions.checkArgument(
                    bulkCopyMaxConcurrent > 0,
                    "'%s' must be a positive integer, but was %s",
                    BULK_COPY_MAX_CONCURRENT.key(),
                    bulkCopyMaxConcurrent);
            Preconditions.checkArgument(
                    bulkCopyDownloadBufferSize > 0,
                    "'%s' must be a positive integer, but was %s",
                    BULK_COPY_DOWNLOAD_BUFFER_SIZE.key(),
                    bulkCopyDownloadBufferSize);
        }

        S3ClientProvider.Builder clientProviderBuilder =
                S3ClientProvider.builder()
                        .accessKey(accessKey)
                        .secretKey(secretKey)
                        .region(region)
                        .endpoint(endpoint)
                        .pathStyleAccess(pathStyleAccess)
                        .chunkedEncoding(config.get(CHUNKED_ENCODING_ENABLED))
                        .checksumValidation(config.get(CHECKSUM_VALIDATION_ENABLED))
                        .maxConnections(maxConnections)
                        .connectionTimeout(config.get(CONNECTION_TIMEOUT))
                        .socketTimeout(config.get(SOCKET_TIMEOUT))
                        .connectionMaxIdleTime(config.get(CONNECTION_MAX_IDLE_TIME))
                        .clientCloseTimeout(config.get(CLIENT_CLOSE_TIMEOUT))
                        .assumeRoleArn(assumeRoleArn)
                        .assumeRoleExternalId(assumeRoleExternalId)
                        .assumeRoleSessionName(assumeRoleSessionName)
                        .assumeRoleSessionDurationSeconds(assumeRoleSessionDuration)
                        .maxRetries(config.get(MAX_RETRIES))
                        .retryBaseDelay(config.get(RETRY_BASE_DELAY))
                        .retryThrottleBaseDelay(config.get(RETRY_THROTTLE_BASE_DELAY))
                        .retryMaxBackoff(config.get(RETRY_MAX_BACKOFF))
                        .retryCircuitBreakerEnabled(config.get(RETRY_CIRCUIT_BREAKER_ENABLED))
                        .credentialsProviderClasses(credentialsProviderClasses)
                        .encryptionConfig(encryptionConfig)
                        .metricPublisher(resolveMetricBridge(config))
                        .useCrt(crtEnabled);

        if (crtEnabled) {
            clientProviderBuilder
                    .crtTargetThroughputGbps(crtTargetThroughputGbps)
                    .crtReadBufferSizeInBytes(
                            crtReadBufferSize == null ? null : crtReadBufferSize.getBytes())
                    .crtMaxConcurrency(crtMaxConcurrency)
                    .crtMaxNativeMemoryLimitInBytes(
                            crtMaxNativeMemoryLimit == null
                                    ? null
                                    : crtMaxNativeMemoryLimit.getBytes())
                    .crtMinPartSizeInBytes(config.get(PART_UPLOAD_MIN_SIZE));
        }
        S3ClientProvider clientProvider = clientProviderBuilder.build();

        NativeS3BulkCopyHelper bulkCopyHelper = null;
        if (bulkCopyEnabled) {
            bulkCopyHelper =
                    new NativeS3BulkCopyHelper(
                            clientProvider.getAsyncClient(),
                            bulkCopyMaxConcurrent,
                            maxConnections,
                            bulkCopyDownloadBufferSize);
        }

        return new NativeS3FileSystem(
                clientProvider,
                fsUri,
                entropyInjectionKey,
                numEntropyChars,
                localTmpDirectory,
                s3minPartSize,
                maxConcurrentUploads,
                bulkCopyHelper,
                useAsyncOperations,
                readBufferSize,
                config.get(FS_CLOSE_TIMEOUT),
                deleteBatchEnabled);
    }

