public static CuratorFrameworkWithUnhandledErrorListener startCuratorFramework(
            Configuration configuration, FatalErrorHandler fatalErrorHandler) {
        checkNotNull(configuration, "configuration");
        String zkQuorum = configuration.getValue(HighAvailabilityOptions.HA_ZOOKEEPER_QUORUM);

        if (zkQuorum == null || StringUtils.isBlank(zkQuorum)) {
            throw new RuntimeException(
                    "No valid ZooKeeper quorum has been specified. "
                            + "You can specify the quorum via the configuration key '"
                            + HighAvailabilityOptions.HA_ZOOKEEPER_QUORUM.key()
                            + "'.");
        }

        int sessionTimeout =
                Math.toIntExact(
                        configuration
                                .get(HighAvailabilityOptions.ZOOKEEPER_SESSION_TIMEOUT)
                                .toMillis());

        int connectionTimeout =
                Math.toIntExact(
                        configuration
                                .get(HighAvailabilityOptions.ZOOKEEPER_CONNECTION_TIMEOUT)
                                .toMillis());

        int retryWait =
                Math.toIntExact(
                        configuration.get(HighAvailabilityOptions.ZOOKEEPER_RETRY_WAIT).toMillis());

        int maxRetryAttempts =
                configuration.get(HighAvailabilityOptions.ZOOKEEPER_MAX_RETRY_ATTEMPTS);

        int maxRetryWait =
                Math.toIntExact(
                        configuration
                                .get(HighAvailabilityOptions.ZOOKEEPER_MAX_RETRY_WAIT)
                                .toMillis());

        String root = configuration.getValue(HighAvailabilityOptions.HA_ZOOKEEPER_ROOT);

        String namespace = configuration.getValue(HighAvailabilityOptions.HA_CLUSTER_ID);

        boolean disableSaslClient = configuration.get(SecurityOptions.ZOOKEEPER_SASL_DISABLE);

        ACLProvider aclProvider;

        ZkClientACLMode aclMode = ZkClientACLMode.fromConfig(configuration);

        if (disableSaslClient && aclMode == ZkClientACLMode.CREATOR) {
            String errorMessage =
                    "Cannot set ACL role to "
                            + ZkClientACLMode.CREATOR
                            + "  since SASL authentication is "
                            + "disabled through the "
                            + SecurityOptions.ZOOKEEPER_SASL_DISABLE.key()
                            + " property";
            LOG.warn(errorMessage);
            throw new IllegalConfigurationException(errorMessage);
        }

        if (aclMode == ZkClientACLMode.CREATOR) {
            LOG.info("Enforcing creator for ZK connections");
            aclProvider = new SecureAclProvider();
        } else {
            LOG.info("Enforcing default ACL for ZK connections");
            aclProvider = new DefaultACLProvider();
        }

        String rootWithNamespace = generateZookeeperPath(root, namespace);

        LOG.info("Using '{}' as Zookeeper namespace.", rootWithNamespace);

        boolean ensembleTracking =
                configuration.get(HighAvailabilityOptions.ZOOKEEPER_ENSEMBLE_TRACKING);

        final CuratorFrameworkFactory.Builder curatorFrameworkBuilder =
                CuratorFrameworkFactory.builder()
                        .connectString(zkQuorum)
                        .sessionTimeoutMs(sessionTimeout)
                        .connectionTimeoutMs(connectionTimeout)
                        .retryPolicy(
                                new BoundedExponentialBackoffRetry(
                                        retryWait, maxRetryWait, maxRetryAttempts))
                        // Curator prepends a '/' manually and throws an Exception if the
                        // namespace starts with a '/'.
                        .namespace(trimStartingSlash(rootWithNamespace))
                        .ensembleTracker(ensembleTracking)
                        .aclProvider(aclProvider);

        if (configuration.contains(HighAvailabilityOptions.ZOOKEEPER_CLIENT_AUTHORIZATION)) {
            Map<String, String> authMap =
                    configuration.get(HighAvailabilityOptions.ZOOKEEPER_CLIENT_AUTHORIZATION);
            List<AuthInfo> authInfos =
                    authMap.entrySet().stream()
                            .map(
                                    entry ->
                                            new AuthInfo(
                                                    entry.getKey(),
                                                    entry.getValue()
                                                            .getBytes(
                                                                    ConfigConstants
                                                                            .DEFAULT_CHARSET)))
                            .collect(Collectors.toList());
            curatorFrameworkBuilder.authorization(authInfos);
        }

        if (configuration.contains(HighAvailabilityOptions.ZOOKEEPER_MAX_CLOSE_WAIT)) {
            long maxCloseWait =
                    configuration.get(HighAvailabilityOptions.ZOOKEEPER_MAX_CLOSE_WAIT).toMillis();
            if (maxCloseWait < 0 || maxCloseWait > Integer.MAX_VALUE) {
                throw new IllegalConfigurationException(
                        "The value (%d ms) is out-of-range for %s. The milliseconds timeout is expected to be between 0 and %d ms.",
                        maxCloseWait,
                        HighAvailabilityOptions.ZOOKEEPER_MAX_CLOSE_WAIT.key(),
                        Integer.MAX_VALUE);
            }
            curatorFrameworkBuilder.maxCloseWaitMs((int) maxCloseWait);
        }

        if (configuration.contains(
                HighAvailabilityOptions.ZOOKEEPER_SIMULATED_SESSION_EXP_PERCENT)) {
            curatorFrameworkBuilder.simulatedSessionExpirationPercent(
                    configuration.get(
                            HighAvailabilityOptions.ZOOKEEPER_SIMULATED_SESSION_EXP_PERCENT));
        }

        if (configuration.get(HighAvailabilityOptions.ZOOKEEPER_TOLERATE_SUSPENDED_CONNECTIONS)) {
            curatorFrameworkBuilder.connectionStateErrorPolicy(
                    new SessionConnectionStateErrorPolicy());
        }
        return startCuratorFramework(curatorFrameworkBuilder, fatalErrorHandler);
    }

public static List<StreamEdge> createChain(
            final Integer currentNodeId,
            final int chainIndex,
            final OperatorChainInfo chainInfo,
            final Map<Integer, OperatorChainInfo> chainEntryPoints,
            final boolean canCreateNewChain,
            final Executor serializationExecutor,
            final JobVertexBuildContext jobVertexBuildContext,
            final @Nullable Consumer<Integer> visitedStreamNodeConsumer) {

        Integer startNodeId = chainInfo.getStartNodeId();
        if (!jobVertexBuildContext.getJobVerticesInOrder().containsKey(startNodeId)) {
            StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();

            // Adaptive graph generator needs to subscribe the visited stream node id to
            // generate hashes for it.
            if (visitedStreamNodeConsumer != null) {
                visitedStreamNodeConsumer.accept(currentNodeId);
            }

            List<StreamEdge> transitiveOutEdges = new ArrayList<StreamEdge>();

            List<StreamEdge> chainableOutputs = new ArrayList<StreamEdge>();
            List<StreamEdge> nonChainableOutputs = new ArrayList<StreamEdge>();

            StreamNode currentNode = streamGraph.getStreamNode(currentNodeId);
            Attribute currentNodeAttribute = currentNode.getAttribute();
            boolean isNoOutputUntilEndOfInput =
                    currentNode.isOutputOnlyAfterEndOfStream()
                            || currentNodeAttribute.isNoOutputUntilEndOfInput();
            if (isNoOutputUntilEndOfInput) {
                currentNodeAttribute.setNoOutputUntilEndOfInput(true);
            }

            for (StreamEdge outEdge : currentNode.getOutEdges()) {
                if (isChainable(outEdge, streamGraph)) {
                    chainableOutputs.add(outEdge);
                } else {
                    nonChainableOutputs.add(outEdge);
                }
            }

            for (StreamEdge chainable : chainableOutputs) {
                StreamNode targetNode = streamGraph.getStreamNode(chainable.getTargetId());
                Attribute targetNodeAttribute = targetNode.getAttribute();
                if (isNoOutputUntilEndOfInput) {
                    if (targetNodeAttribute != null) {
                        targetNodeAttribute.setNoOutputUntilEndOfInput(true);
                    }
                }
                transitiveOutEdges.addAll(
                        createChain(
                                chainable.getTargetId(),
                                chainIndex + 1,
                                chainInfo,
                                chainEntryPoints,
                                canCreateNewChain,
                                serializationExecutor,
                                jobVertexBuildContext,
                                visitedStreamNodeConsumer));
                // Mark upstream nodes in the same chain as outputBlocking
                if (targetNodeAttribute != null
                        && targetNodeAttribute.isNoOutputUntilEndOfInput()) {
                    currentNodeAttribute.setNoOutputUntilEndOfInput(true);
                }
            }

            for (StreamEdge nonChainable : nonChainableOutputs) {
                transitiveOutEdges.add(nonChainable);
                // Used to control whether a new chain can be created, this value is true in the
                // full graph generation algorithm and false in the progressive generation
                // algorithm. In the future, this variable can be a boolean type function to adapt
                // to more adaptive scenarios.
                if (canCreateNewChain) {
                    createChain(
                            nonChainable.getTargetId(),
                            1, // operators start at position 1 because 0 is for chained source
                            // inputs
                            chainEntryPoints.computeIfAbsent(
                                    nonChainable.getTargetId(),
                                    (k) -> chainInfo.newChain(nonChainable.getTargetId())),
                            chainEntryPoints,
                            canCreateNewChain,
                            serializationExecutor,
                            jobVertexBuildContext,
                            visitedStreamNodeConsumer);
                }
            }

            chainInfo.addChainedName(
                    currentNodeId,
                    createChainedName(
                            currentNodeId,
                            chainableOutputs,
                            Optional.ofNullable(chainEntryPoints.get(currentNodeId)),
                            chainInfo.getChainedNames(),
                            jobVertexBuildContext));

            chainInfo.addChainedMinResources(
                    currentNodeId,
                    createChainedMinResources(
                            currentNodeId, chainableOutputs, chainInfo, jobVertexBuildContext));

            chainInfo.addChainedPreferredResources(
                    currentNodeId,
                    createChainedPreferredResources(
                            currentNodeId, chainableOutputs, chainInfo, jobVertexBuildContext));

            OperatorID currentOperatorId =
                    chainInfo.addNodeToChain(
                            currentNodeId,
                            streamGraph.getStreamNode(currentNodeId).getOperatorName(),
                            jobVertexBuildContext);

            if (currentNode.getInputFormat() != null) {
                chainInfo
                        .getOrCreateFormatContainer()
                        .addInputFormat(currentOperatorId, currentNode.getInputFormat());
            }

            if (currentNode.getOutputFormat() != null) {
                chainInfo
                        .getOrCreateFormatContainer()
                        .addOutputFormat(currentOperatorId, currentNode.getOutputFormat());
            }
            OperatorInfo operatorInfo =
                    chainInfo.createAndGetOperatorInfo(currentNodeId, currentOperatorId);

            StreamConfig config;
            if (currentNodeId.equals(startNodeId)) {
                JobVertex jobVertex = jobVertexBuildContext.getJobVertex(startNodeId);
                if (jobVertex == null) {
                    jobVertex =
                            createJobVertex(
                                    chainInfo, serializationExecutor, jobVertexBuildContext);
                }
                config = new StreamConfig(jobVertex.getConfiguration());
            } else {
                config = new StreamConfig(new Configuration());
            }

            tryConvertPartitionerForDynamicGraph(
                    chainableOutputs, nonChainableOutputs, jobVertexBuildContext);
            config.setAttribute(currentNodeAttribute);
            config.setWatermarkDeclarations(streamGraph.getSerializedWatermarkDeclarations());
            setOperatorConfig(currentNodeId, config, chainInfo, jobVertexBuildContext);

            setOperatorChainedOutputsConfig(config, chainableOutputs, jobVertexBuildContext);
            // we cache the non-chainable outputs here, and set the non-chained config later
            operatorInfo.addNonChainableOutputs(nonChainableOutputs);

            if (currentNodeId.equals(startNodeId)) {
                chainInfo.setTransitiveOutEdges(transitiveOutEdges);
                jobVertexBuildContext.addChainInfo(startNodeId, chainInfo);

                config.setChainStart();
                config.setChainIndex(chainIndex);
                config.setOperatorName(streamGraph.getStreamNode(currentNodeId).getOperatorName());
                config.setTransitiveChainedTaskConfigs(
                        jobVertexBuildContext.getChainedConfigs().get(startNodeId));
            } else {
                config.setChainIndex(chainIndex);
                StreamNode node = streamGraph.getStreamNode(currentNodeId);
                config.setOperatorName(node.getOperatorName());
                jobVertexBuildContext
                        .getOrCreateChainedConfig(startNodeId)
                        .put(currentNodeId, config);
            }

            config.setOperatorID(currentOperatorId);

            if (chainableOutputs.isEmpty()) {
                config.setChainEnd();
            }
            return transitiveOutEdges;

        } else {
            return new ArrayList<>();
        }
    }

